export async function recursiveAdversarialTester(moduleOutputs, adversarialConditions) {
  const results = [];
  for (const output of moduleOutputs) {
    const adversarialResults = adversarialConditions.map(condition => {
      return condition.test(output);
    });
    results.push({ output, adversarialResults });
  }
  const refinedOutputs = results.filter(result => {
    return result.adversarialResults.every(res => res.passed);
  }).map(result => result.output);
  return refinedOutputs;
}